std::complex<double> A52(int j1, int j2, int j3, int j4, int j5, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  using namespace constants_mod;
  using namespace mxpart_mod;
  using namespace sprods_com_mod;
  using namespace scale_mod;
  using namespace epinv_mod;
  using namespace epinv2_mod;

  std::complex<double> Vcc, Fcc, Vsc, Fsc, l12, l45, A5lom;
  double s123;

  auto zab2 = [&za, &zb](int i1, int i2, int i3, int i4) { 
      return za(i1,i2)*zb(i2,i4) + za(i1,i3)*zb(i3,i4); 
  };


  s123 = s(j1, j2) + s(j2, j3) + s(j3, j1);

  l12 = lnrat(musq, -s(j1, j2));
  l45 = lnrat(musq, -s(j4, j5));
  A5lom = za(j2, j4) * zab2(j2,j1,j3,j5) / (za(j2, j3) * za(j3, j1) * s123);
  Vcc = -(epinv * epinv2 + epinv * l12 + half * std::pow(l12, 2)) - two * (epinv + l45) - four;
  Fcc = -za(j2, j4) * zab2(j2,j1,j3,j5) / (za(j2, j3) * za(j3, j1) * s123)
        * Lsm1(-s(j1, j2), -s123, -s(j1, j3), -s123)
        + zab2(j2,j1,j3,j5) * (za(j1, j2) * za(j3, j4) - za(j1, j4) * za(j2, j3))
        / (za(j2, j3) * std::pow(za(j1, j3), 2) * s123)
        * Lsm1(-s(j1, j2), -s123, -s(j2, j3), -s123)
        + two * zb(j1, j3) * za(j1, j4) * zab2(j2,j1,j3,j5) / (za(j1, j3) * s123)
        * L0(-s(j2, j3), -s123) / s123;

  Vsc = half * (epinv + l45) + half;
  Fsc = za(j1, j4) * za(j2, j3) * zab2(j1,j2,j3,j5) / (std::pow(za(j1, j3), 3) * s123)
        * Lsm1(-s(j1, j2), -s123, -s(j2, j3), -s123)
        + half * za(j4, j1) * std::pow(zb(j1, j3), 2) * za(j2, j3) * zab2(j1,j2,j3,j5)
        / (za(j1, j3) * s123) * L1(-s123, -s(j2, j3)) / std::pow(s(j2, j3), 2)
        + za(j1, j4) * za(j2, j3) * zb(j3, j1) * zab2(j1,j2,j3,j5) 
        / (std::pow(za(j1, j3), 2) * s123) * L0(-s123, -s(j2, j3)) / s(j2, j3)
        - za(j2, j1) * zb(j1, j3) * za(j4, j3) * zb(j3, j5) / za(j1, j3)
        * L1(-s123, -s(j1, j2)) / std::pow(s(j1, j2), 2)
        - za(j2, j1) * zb(j1, j3) * za(j3, j4) * zab2(j1,j2,j3,j5)
        / (std::pow(za(j1, j3), 2) * s123) * L0(-s123, -s(j1, j2)) / s(j1, j2)
        + half * zab2(j4,j1,j2,j3) * (zb(j1, j3) * zb(j2, j5) + zb(j2, j3) * zb(j1, j5))
        / (zb(j1, j2) * zb(j2, j3) * za(j1, j3) * s123);

  return (Vcc + Vsc) * A5lom + Fcc + Fsc;
}

extern "C" {
  std::complex<double> A52_wrapper(int j1, int j2, int j3, int j4, int j5, std::complex<double>* za_ptr, std::complex<double>* zb_ptr) {

    using namespace mxpart_mod;

    FArray2D<std::complex<double>> za(za_ptr, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(zb_ptr, mxpart, mxpart);

    return A52(j1, j2, j3, j4, j5, za, zb);
  }
}

